jobs, fehlt = [], []
for jid, j in alt.items():
    if "drache" in jid and jid not in ("drachenschildkroete", "pseudodrache", "halbroter-drachenveteran"):
        alter = next(a for a in ALTER if jid.startswith(a) or jid.endswith(a))
        farbe = next(f for f in FARBEN if f in jid.replace("ae", "").replace("drachennestling", ""))
        en_f, f_text = FARBEN[farbe]
        en_a, a_text = ALTER[alter]
        if alter == "nestling":
            motiv = f"a {en_f} dragon wyrmling"
        else:
            motiv = f"an {en_a} {en_f} dragon" if en_a[0] in "aeiou" else f"a {en_a} {en_f} dragon"
        look, rahmen = a_text.format(f=f_text), "head and long neck"
    elif jid in L:
        motiv, look = L[jid]
        rahmen = RAHMEN.get(jid) or (GANZ if jid in GANZE_GESTALT else "head and shoulders")
    else:
        fehlt.append(jid)
        continue
    jobs.append({"id": jid, "name": j["name"], "art": "portraet", "stil": "fantasy-dunkel", "motiv": motiv,
                 "rahmen": rahmen, "looks": [f"{look}, {v}" for v in ANSICHTEN.get(jid, VARIANTEN)],
                 "typ": j.get("type"), "groesse": j.get("size"), "neg": j.get("neg", "")})
if fehlt:
    raise SystemExit(f"Ohne Beschreibung: {fehlt}")
(SDXL / "jobs-flux-portraets.json").write_text(json.dumps(jobs, ensure_ascii=False, indent=1), encoding="utf-8")
